-- public.set_market_retired
-- Generated by scripts/schema-snapshot.mjs from project heuhqqoxyggawuckxocp. Do not edit by hand.

-- SECURITY DEFINER; API roles that may call it: authenticated, service_role
CREATE OR REPLACE FUNCTION public.set_market_retired(p_market uuid, p_retired boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.is_global_admin() then
    raise exception 'Only the Tryp.com team can retire a market';
  end if;
  if (select kind from public.communities where id = p_market) <> 'chapter' then
    raise exception 'The network itself cannot be retired';
  end if;

  update public.communities
     set retired_at = case when p_retired then now() else null end,
         -- Retiring closes it too. A retired market that is still "open" would
         -- keep accepting joins from anybody whose country matches.
         is_active  = case when p_retired then false else is_active end
   where id = p_market;

  insert into public.admin_audit_log (actor_id, actor_name, action, target_id, target_name)
  select auth.uid(), (select name from public.profiles where id = auth.uid()),
         case when p_retired then 'Retired a market' else 'Reopened a market' end,
         p_market, (select name from public.communities where id = p_market);
end;
$function$;
